// IP Protection limits
// 27: Grid voltage Upper limit (0.1V)
// 28: Grid voltage Lower limit (0.1V)
// 29: Grid frequency upper limit (0.01Hz)
// 30: Grid frequency lower limit (0.01Hz)

msg.baseAddr = 27;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 27,
    quantity: 4
};
return msg;

// Over frequency derating
// 35: OverFrq_De_rate (0-100%)

msg.baseAddr = 35;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 35,
    quantity: 1
};
return msg;

// LVRT/HVRT settings (California LHVRT)
// 331: CA_LHVRT enable
// 332: CA_HV2, 333: CA_HV1
// 334: CA_LV1, 335: CA_LV2, 336: CA_LV3
// 337: CA_HV2_Time, 338: CA_HV1_Time
// 339: CA_LV1_Time, 340: CA_LV2_Time, 341: CA_LV3_Time

msg.baseAddr = 331;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 331,
    quantity: 11
};
return msg;

// V(Q) curve (California QV)
// 351: CA_QV enable
// 352-355: CA_QV_V1 to V4
// 356-359: CA_QV_Q1 to Q4

msg.baseAddr = 351;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 351,
    quantity: 9
};
return msg;

// F(W) and V(W) curves
// 360: CA_FW enable
// 361: CA_Fstart
// 362: CA_Fstop
// 363: CA_VW enable
// 364: CA_Vstart
// 365: CA_Vstop

msg.baseAddr = 360;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 360,
    quantity: 6
};
return msg;

// Build GridAdvancedProtectionConfigState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("GridAdvancedProtectionConfigState: missing base address");
    return null;
}

// ---- Store partials ----

// IP Limits 27-30
if (baseAddr === 27) {
    flow.set("gapc_part_ip_limits", {
        hv1OverVoltageV: Math.round((data[0] || 0) * 0.1 * 10) / 10,   // 27
        lv1UnderVoltageV: Math.round((data[1] || 0) * 0.1 * 10) / 10,  // 28
        hf1OverFrequencyHz: Math.round((data[2] || 0) * 0.01 * 100) / 100,  // 29
        lf1UnderFrequencyHz: Math.round((data[3] || 0) * 0.01 * 100) / 100  // 30
    });
}

// Freq Derate 35
else if (baseAddr === 35) {
    flow.set("gapc_part_freq_derate", {
        overFrqDeRate: data[0] || 0  // 0-100%
    });
}

// LVRT 331-341
else if (baseAddr === 331) {
    flow.set("gapc_part_lvrt", {
        lvrtEnabled: (data[0] || 0) === 1,         // 331
        hv2Voltage: data[1] || 0,                  // 332
        hv1Voltage: data[2] || 0,                  // 333
        lv1Voltage: data[3] || 0,                  // 334
        lv2Voltage: data[4] || 0,                  // 335
        lv3Voltage: data[5] || 0,                  // 336
        hv2Time: data[6] || 0,                     // 337
        hv1Time: data[7] || 0,                     // 338
        lv1Time: data[8] || 0,                     // 339
        lv2Time: data[9] || 0,                     // 340
        lv3Time: data[10] || 0                     // 341
    });
}

// QV 351-359
else if (baseAddr === 351) {
    flow.set("gapc_part_qv", {
        qvEnabled: (data[0] || 0) === 1,           // 351
        v1: data[1] || 0,                          // 352
        v2: data[2] || 0,                          // 353
        v3: data[3] || 0,                          // 354
        v4: data[4] || 0,                          // 355
        q1: data[5] || 0,                          // 356
        q2: data[6] || 0,                          // 357
        q3: data[7] || 0,                          // 358
        q4: data[8] || 0                           // 359
    });
}

// FW/VW 360-365
else if (baseAddr === 360) {
    flow.set("gapc_part_fw_vw", {
        fwEnabled: (data[0] || 0) === 1,           // 360
        fStart: Math.round((data[1] || 0) * 0.01 * 100) / 100,  // 361
        fStop: Math.round((data[2] || 0) * 0.01 * 100) / 100,   // 362
        vwEnabled: (data[3] || 0) === 1,           // 363
        vStart: Math.round((data[4] || 0) * 0.1 * 10) / 10,     // 364
        vStop: Math.round((data[5] || 0) * 0.1 * 10) / 10       // 365
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const ipLimitsPart = flow.get("gapc_part_ip_limits");
const freqDeratePart = flow.get("gapc_part_freq_derate");
const lvrtPart = flow.get("gapc_part_lvrt");
const qvPart = flow.get("gapc_part_qv");
const fwVwPart = flow.get("gapc_part_fw_vw");

if (!ipLimitsPart || !freqDeratePart || !lvrtPart || !qvPart || !fwVwPart) {
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";

const state = {
    kind: "GridAdvancedProtectionConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,
    version: "1",

    ipProtection: {
        hv1OverVoltageV: ipLimitsPart.hv1OverVoltageV,
        hv1TripTimeSeconds: null,  // Not available
        hv2OverVoltageV: null,
        hv2TripTimeSeconds: null,
        hv3OverVoltageV: null,
        hv3TripTimeSeconds: null,

        lv1UnderVoltageV: ipLimitsPart.lv1UnderVoltageV,
        lv1TripTimeSeconds: null,
        lv2UnderVoltageV: null,
        lv2TripTimeSeconds: null,
        lv3UnderVoltageV: null,
        lv3TripTimeSeconds: null,

        hf1OverFrequencyHz: ipLimitsPart.hf1OverFrequencyHz,
        hf1TripTimeSeconds: null,
        hf2OverFrequencyHz: null,
        hf2TripTimeSeconds: null,
        hf3OverFrequencyHz: null,
        hf3TripTimeSeconds: null,

        lf1UnderFrequencyHz: ipLimitsPart.lf1UnderFrequencyHz,
        lf1TripTimeSeconds: null,
        lf2UnderFrequencyHz: null,
        lf2TripTimeSeconds: null,
        lf3UnderFrequencyHz: null,
        lf3TripTimeSeconds: null,

        tenMinuteOverVoltageV: null
    },

    frequencyPowerDroop: {
        enabled: fwVwPart.fwEnabled,
        overFrequency: {
            startFreqHz: fwVwPart.fStart,
            stopFreqHz: fwVwPart.fStop,
            droopPercentPerHz: freqDeratePart.overFrqDeRate,
            startDelaySeconds: null,
            stopDelaySeconds: null
        },
        underFrequency: {
            startFreqHz: null,
            stopFreqHz: null,
            droopPercentPerHz: null,
            startDelaySeconds: null,
            stopDelaySeconds: null
        }
    },

    voltageActivePowerCurve: {
        enabled: fwVwPart.vwEnabled,
        lockInPnPercent: null,
        lockOutPnPercent: null,
        points: [
            { voltagePercent: fwVwPart.vStart, powerPercent: null },
            { voltagePercent: fwVwPart.vStop, powerPercent: null },
            { voltagePercent: null, powerPercent: null },
            { voltagePercent: null, powerPercent: null }
        ]
    },

    voltageReactivePowerCurve: {
        enabled: qvPart.qvEnabled,
        lockInPnPercent: null,
        lockOutPnPercent: null,
        points: [
            { voltagePercent: qvPart.v1, reactivePercent: qvPart.q1 },
            { voltagePercent: qvPart.v2, reactivePercent: qvPart.q2 },
            { voltagePercent: qvPart.v3, reactivePercent: qvPart.q3 },
            { voltagePercent: qvPart.v4, reactivePercent: qvPart.q4 }
        ]
    },

    activeVsReactiveCurve: {
        enabled: null,
        points: [
            { activePowerPercent: null, reactivePercent: null },
            { activePowerPercent: null, reactivePercent: null },
            { activePowerPercent: null, reactivePercent: null },
            { activePowerPercent: null, reactivePercent: null }
        ]
    },

    activeVsPowerFactorCurve: {
        enabled: null,
        lockInPnPercent: null,
        lockOutPnPercent: null,
        pfPoints: [
            { activePowerPercent: null, powerFactor: null },
            { activePowerPercent: null, powerFactor: null },
            { activePowerPercent: null, powerFactor: null },
            { activePowerPercent: null, powerFactor: null }
        ]
    },

    voltageRideThrough: {
        enabled: lvrtPart.lvrtEnabled,
        hvLevels: [
            { voltagePercent: lvrtPart.hv2Voltage, timeSeconds: lvrtPart.hv2Time },
            { voltagePercent: lvrtPart.hv1Voltage, timeSeconds: lvrtPart.hv1Time },
            { voltagePercent: null, timeSeconds: null }
        ],
        lvLevels: [
            { voltagePercent: lvrtPart.lv1Voltage, timeSeconds: lvrtPart.lv1Time },
            { voltagePercent: lvrtPart.lv2Voltage, timeSeconds: lvrtPart.lv2Time },
            { voltagePercent: lvrtPart.lv3Voltage, timeSeconds: lvrtPart.lv3Time }
        ]
    }
};

// Clear partials
flow.set("gapc_part_ip_limits", null);
flow.set("gapc_part_freq_derate", null);
flow.set("gapc_part_lvrt", null);
flow.set("gapc_part_qv", null);
flow.set("gapc_part_fw_vw", null);

flow.set("gridAdvancedProtectionConfigSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;
